css:
/* Arena Quiz — generated by NoaCG Studio. Edit freely: this file is yours. */

/* ── Style contract: change these variables to retint the whole graphic. ── */
:root {
  --accent: #3d6bff;           /* the one accent color */
  --text-color: #ffffff;          /* primary text */
  --text-dim: rgba(255,255,255,0.72);  /* secondary text (title line) */
  --panel-bg: rgba(8, 10, 20, 0.94);  /* the panel behind the text */
  --font-heading: "Archivo", Arial, sans-serif;  /* the graphic's typeface */
  --scale: 1;                  /* whole-graphic size multiplier (also handles resolution) */
  --type-scale: 1;                  /* text-only size multiplier (on top of --scale) */
  --panel-radius: 0;                            /* panel corner radius */
  --accent-weight: calc(10px * var(--scale));   /* thickness of the accent bar */
  --accent-ink: var(--panel-bg);                /* text colour on an accent-filled chip */
  --display-weight: 800;                        /* heading weight */
  --display-tracking: 0.01em;                   /* heading letter-spacing (big text tightens) */
}

/* Bundled open-source font (the file ships with the export — no internet at playout). */
@font-face {
  font-family: "Archivo";
  src: url("fonts/archivo.woff2") format("woff2");
  font-weight: 400 900;  /* variable font: covers this weight range */
  font-display: swap;          /* show fallback text until the font loads */
}

/* Reset and a transparent canvas (broadcast graphics render over video). */
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  width: 1920px;
  height: 1080px;
  overflow: hidden;                /* nothing ever scrolls on air */
  background: transparent;
  font-family: var(--font-heading);
}

/* ── Root position (anchor zone) ── */
.quiz {
  position: absolute;
  left: calc(50% + 0px);           /* anchored to the horizontal center */
  top: calc(50% + 0px);            /* anchored to the vertical center */
  transform: translateX(-50%) translateY(-50%);/* center on the anchor point */
  text-align: center;              /* lines align toward the anchor edge */
  opacity: 0;                      /* hidden until play() runs the entrance */
}

/* ── Auto-fit: the panel hugs its content and wraps instead of overflowing. ── */
.quiz-box {
  --stage-width: 1110px;      /* the room this board was drawn for — this panel's width is the design's, never the text's */
  width: 1110px;  /* fallback: no CSS min() before Chromium 79 (older CasparCG) */
  width: min(calc(1110px * var(--scale)), 1680px);
  box-sizing: border-box;          /* the declared width includes the panel's own padding */
  justify-content: center;       /* short content leaves the room where the anchor already reads */
  max-width: 1680px;  /* fallback: no CSS min() before Chromium 79 (older CasparCG) */
  max-width: min(calc(1190px * var(--scale)), 1680px);  /* the wrap cap — follows --scale, stops at the safe area */
  will-change: transform, opacity; /* hint the browser: this element animates */
}
.quiz-mask {
  overflow: hidden;                /* the question animates in from behind this mask */
}
.quiz-mask > span {
  display: inline-block;           /* so the question can move inside its mask */
  overflow-wrap: break-word;       /* break very long unbroken words */
  text-wrap: balance;              /* wrapped rows get even lengths */
}
.quiz-option {
  will-change: transform, opacity; /* the rows stagger in and pop on reveal */
}

/* ── Audience result chips — the per-answer percentages the audience state paints. The chip
      anchors to its row's right edge; rows get position only while the result shows, so a
      design's own layout is untouched the rest of the time. Numerals stay tabular so a live
      count never changes width as its digits change. ── */
.quiz-audience .quiz-option { position: relative; }
.quiz-aud {
  position: absolute;
  right: calc(14px * var(--scale));
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--font-numeric, inherit);
  font-variant-numeric: tabular-nums;
  font-size: calc(21px * var(--scale) * var(--type-scale));
  font-weight: 600;
  opacity: 0.92;
}

/* ── Design ── */
/* The card: the preset tweens THIS element (y + opacity), so it carries no lean of its
   own - the slab and the accent edge are painted on pseudo-layers below. */
.quiz-box {
  position: relative;              /* anchors the painted slab (::before) and edge (::after) */
  padding: calc(30px * var(--scale)) calc(48px * var(--scale));  /* wide sides keep text clear
                                      of the slab's slanted edges on a card this tall */
}

/* The painted slab: the sport lean lives HERE, on a background layer no preset ever tweens
   (same doctrine as lt05 Angle Slab - the family's -8deg signature survives every tween). */
.quiz-box::before {
  content: '';                     /* pseudo-elements render only with content set */
  position: absolute;              /* fills the box exactly ... */
  top: 0; right: 0; bottom: 0; left: 0;  /* ... edge to edge. The four longhands rather than the
                                      inset shorthand: inset needs Chromium 87, and an older
                                      CasparCG CEF DROPS the whole declaration - which collapses
                                      this slab to nothing and takes the card's background off
                                      air (measured on a real 2.3.x server, 2026-08-06). */
  z-index: -1;                     /* paints behind the question and the rows */
  background: var(--panel-bg);     /* near-black slab behind everything */
  border-radius: var(--panel-radius);  /* the family's panel corner radius */
  transform: skewX(-8deg);         /* SKEW: the whole card leans forward, mid-sprint */
}

/* The accent edge: a chunky 10px slab fused to the card's leaning left side. Same height
   and same skew as the slab, so both left edges stay perfectly parallel. */
.quiz-box::after {
  content: '';                     /* second painted layer on the same box */
  position: absolute;              /* pinned over the slab's left edge ... */
  left: 0;                         /* ... flush with the box's left side */
  top: 0;                          /* full height, top ... */
  bottom: 0;                       /* ... to bottom */
  z-index: -1;                     /* behind the text, above ::before (later layer wins) */
  width: var(--accent-weight);     /* the family's accent edge weight */
  background: var(--accent);       /* the family's loud color moment */
  transform: skewX(-8deg);         /* leans with the slab so the two fuse into one shape */
}

/* The question: condensed heavy caps - the loudest thing on the card. */
.quiz-mask > span {
  font-size: calc(40px * var(--scale) * var(--type-scale));  /* headline scale for a multi-row card */
  font-weight: var(--display-weight);  /* the question's authored display weight */
  line-height: 1.15;               /* tight - big text needs little leading */
  letter-spacing: var(--display-tracking);  /* the question's authored display tracking */
  text-transform: uppercase;       /* quiz questions are shouted, not spoken */
  color: var(--text-color);        /* primary text on the dark slab */
}

/* The answer stack: four uniform rows under the question, zero-radius sport rhythm. */
.quiz-options {
  margin-top: calc(24px * var(--scale));  /* clear break between question and answers */
  display: flex;                   /* a simple vertical stack ... */
  flex-direction: column;          /* ... one row per answer */
}

/* The air between rows as a MARGIN rather than a flex gap: gap in a flex container needs
   Chromium 84, and an older CasparCG CEF drops it, stacking the four answers flush against
   each other. An adjacent-sibling margin paints the same picture on every engine, and it also
   costs the first row nothing - which is what the gap was buying. */
.quiz-option + .quiz-option {
  margin-top: calc(12px * var(--scale));  /* even air between the rows */
}

/* One answer row: the preset staggers these in and pops the winner, so the row itself is
   never skewed - its chip background leans on the ::before layer below. */
.quiz-option {
  position: relative;              /* anchors the painted row chip (::before) */
  display: flex;                   /* letter block + answer text side by side */
  align-items: center;             /* text centers on the letter block's height */
  height: calc(46px * var(--scale));  /* uniform row height - the letter block fills it */
}

/* The row chip: a faint slab behind each answer. color-mix keeps it on-palette - it is
   the text color at 8%, so the Style panel retints it along with everything else. */
.quiz-option::before {
  content: '';                     /* painted layer - safe from every preset tween */
  position: absolute;              /* fills the row exactly ... */
  top: 0; right: 0; bottom: 0; left: 0;  /* ... edge to edge (longhands, not inset - see above) */
  z-index: -1;                     /* behind the letter block and the text */
  background: rgba(255, 255, 255, 0.08);  /* fallback: no color-mix() before Chromium 111, and
                                      without this the answer chips are simply absent on an
                                      older CasparCG - which is exactly how this board went on
                                      air as "just the blue line and the numbers" */
  background: color-mix(in srgb, var(--text-color) 8%, transparent);  /* faint on-palette tint */
  border-radius: 0;                /* hard corners - sport shape language */
  transform: skewX(-8deg);         /* the family lean, parallel to the card slab */
}

/* The letter block: a solid accent slab leading each row. The block leans on ITS ::before,
   so the letter itself stays dead straight with no counter-skew needed. */
.quiz-letter {
  position: relative;              /* anchors the painted accent block (::before) */
  flex-shrink: 0;                  /* the block never squeezes; text takes the rest */
  width: calc(48px * var(--scale));   /* a chunky square-ish block ... */
  height: 100%;                    /* ... filling the row's full height */
  display: flex;                   /* centers the letter ... */
  align-items: center;             /* ... vertically */
  justify-content: center;         /* ... and horizontally */
  margin-right: calc(18px * var(--scale));  /* air between the block and the answer text */
  font-size: calc(22px * var(--scale) * var(--type-scale));  /* the letter - loud but under the answers */
  font-weight: 800;                /* block letters hit hard */
  color: var(--accent-ink);        /* the family's ink on an accent-filled block */
}

/* The letter block's paint: solid accent, leaning with the rest of the family. */
.quiz-letter::before {
  content: '';                     /* painted layer behind the letter */
  position: absolute;              /* fills the block exactly ... */
  top: 0; right: 0; bottom: 0; left: 0;  /* ... edge to edge (longhands, not inset - see above) */
  z-index: -1;                     /* behind the letter glyph */
  background: var(--accent);       /* four small accent doses - sport uses accent boldly */
  transform: skewX(-8deg);         /* the family lean - fuses with the row chip's edge */
}

/* The answer text: condensed caps, clearly under the question. */
.quiz-text {
  font-size: calc(24px * var(--scale) * var(--type-scale));  /* list scale - subordinate to the 40px question */
  font-weight: 700;                /* heavy enough to read at a glance */
  letter-spacing: 0.04em;          /* slight air between the caps */
  text-transform: uppercase;       /* the whole card shouts */
  color: var(--text-color);        /* primary text on the dark slab */
  padding-right: calc(20px * var(--scale));  /* text never touches the chip's slanted edge */
  overflow-wrap: break-word;       /* break very long unbroken answers */
}

/* ── The reveal (SPX Continue) ── */

/* Correct: the row's chip floods solid accent - the game-show money moment. */
.quiz-correct::before {
  background: var(--accent);       /* the faint chip becomes the loud accent slab */
}

/* Correct: dark ink on the flooded chip (the panel hue doubles as text, like lt06's bar). */
.quiz-correct .quiz-text {
  color: var(--accent-ink);        /* the family's ink on an accent-filled row */
  font-weight: 800;                /* the winner steps up a weight */
}

/* Correct: the letter block inverts - a strong dark edge leading the flooded row. */
.quiz-correct .quiz-letter {
  color: var(--accent);            /* accent letter ... */
}
.quiz-correct .quiz-letter::before {
  background: var(--panel-bg);     /* ... on a dark block - the row's hard leading edge */
}

/* Dim: fade the row's LAYERS, not the row - the entrance tween leaves an inline
   opacity on .quiz-option itself, which would override a plain .quiz-dim opacity rule. */
.quiz-dim::before,
.quiz-dim .quiz-letter,
.quiz-dim .quiz-text {
  opacity: 0.35;                   /* wrong answers drop back, still readable */
}

/* ── The selection arc (the state machine's events) ── */

/* Selected: the contestant's pick, before anyone knows if it is right. A keyline ring only -
   the flood is reserved for the reveal, so the two moments never look alike. */
.quiz-sel::before {
  box-shadow: inset 0 0 0 calc(3px * var(--scale)) var(--accent);
}

/* Locked: the unpicked rows step back, so the chosen row is unmistakably the standing answer.
   The machine is what makes it final; this is how the viewer sees that it did. */
.quiz-locked .quiz-option:not(.quiz-sel) .quiz-letter,
.quiz-locked .quiz-option:not(.quiz-sel) .quiz-text {
  opacity: 0.55;                   /* quieter than a dim - the question is still live */
}

/* Wrong: the pick that lost. The family's semantic down-colour, the same escape hatch the
   market tickers take for a falling value - it never becomes a second brand accent. */
.quiz-wrong::before {
  box-shadow: inset 0 0 0 calc(3px * var(--scale)) #e57a7d;
}
.quiz-wrong .quiz-letter {
  color: #e57a7d;                  /* the losing row's leading edge carries the colour */
}

/* Hidden data sources — holders SPX writes into and the runtime reads, never drawn.
   The rule lives in the stylesheet on purpose: an inline display:none would be wiped by the
   editor's entrance reset (it clears inline props) and the value would appear on screen. */
.noacg-data-source {
  display: none;                   /* input only: written by SPX, read by JS, never rendered */
}

js:
// Arena Quiz — generated by NoaCG Studio. SPX calls update(), play(), stop(), next().

// motionSpeed(): the template's speed knob. The NOACG_ANIM data block owns it; a legacy
// animSpeed variable is honored too, and hand-written animation code defaults to 1.
function motionSpeed() {
  if (typeof NOACG_ANIM !== 'undefined' && NOACG_ANIM.speed) return NOACG_ANIM.speed;
  if (typeof animSpeed !== 'undefined' && animSpeed) return animSpeed;
  return 1;
}

// Write one field value into its element. Text fields get plain
// text (operator input never runs as HTML); an <img id="fN"> gets the value as its image path.
function setFieldValue(el, value) {
  if (el.tagName === 'IMG') {
    if (value) { el.src = value; el.style.display = ''; }
    else { el.removeAttribute('src'); el.style.display = 'none'; }  // empty = show the design's placeholder
    // The img's parent gets .has-image so the CSS can hide a placeholder mark, resize, etc.
    if (el.parentNode && el.parentNode.classList) el.parentNode.classList.toggle('has-image', !!value);
  } else if (el.tagName === 'image') {
    // An SVG picture slot (an imported design's own <image> layer): swap its href. Empty
    // restores the picture the designer drew, so an untouched field changes nothing.
    if (!el.hasAttribute('data-orig-href')) el.setAttribute('data-orig-href', el.getAttribute('href') || '');
    el.setAttribute('href', value || el.getAttribute('data-orig-href'));
  } else {
    el.textContent = value;
  }
}

// clearReveal(): remove a previous reveal so the graphic is back to the neutral state
// (fresh data, replay, or a second question all start un-revealed). It clears the SELECTION
// and the lock too: a visual reset that left a board looking judged would be a lie, and snap
// clears inline styles but never classes.
function clearReveal() {
  var options = document.querySelectorAll('.quiz-option');
  for (var i = 0; i < options.length; i++) {
    options[i].classList.remove('quiz-correct');
    options[i].classList.remove('quiz-dim');
    options[i].classList.remove('quiz-sel');
    options[i].classList.remove('quiz-wrong');
    var chip = options[i].querySelector('.quiz-aud');
    if (chip) chip.parentNode.removeChild(chip);
  }
  var root = document.querySelector('.quiz');
  if (root) {
    root.classList.remove('quiz-locked');
    root.classList.remove('quiz-audience');
    root.removeAttribute('data-noacg-paint'); // the paint signature died with the marks
  }
}

// quizRow(letter): the option row a letter names, or null. A -> row 0, B -> row 1, …
// THE EMPTY STRING IS NOT A LETTER, and it has to be rejected before the lookup rather than by
// it: 'ABCD'.indexOf('') is 0 in every JS engine, so an unset pick used to resolve to
// ROW A. The selected-answer field starts empty by design (nobody has picked yet), so entering
// the selected state on a board nobody had typed an answer into marked the first answer as the
// contestant's - a wrong pick on air, with no operator action behind it and nothing to
// distinguish it from a real one.
function quizRow(letter) {
  var name = String(letter || '').trim().toUpperCase();
  var index = name ? 'ABCD'.indexOf(name) : -1;
  var options = document.querySelectorAll('.quiz-option');
  return index === -1 ? null : (options[index] || null);
}

// The PAINT SIGNATURE: what the board currently shows, as one string — the machine state plus
// the two letters that drive the marks. ONLY a FULL repaint may stamp it (paintQuizState, and
// revealAnswer — which clears first): a partial painter certifying it would lie after a SNAP,
// where the target state's own call fires (applyLock) but the previous state's classes remain
// (snap clears inline styles, never classes) — a stamped signature then made the trailing
// data write's repaint a no-op and the stale verdict stayed on air. clearReveal removes it.
function quizPaintSig() {
  var state = (typeof noacgMachineState === 'function') ? ((noacgMachineState().groups || {}).main || '') : '';
  var pickedEl = document.getElementById('f6');
  var correctEl = document.getElementById('f5');
  var resultsEl = document.getElementById('f7');
  return state + '|' + (correctEl ? correctEl.textContent : '') + '|' + (pickedEl ? pickedEl.textContent : '')
    + '|' + (resultsEl ? resultsEl.textContent : '');
}
function markQuizPaint() {
  var root = document.querySelector('.quiz');
  if (root) root.setAttribute('data-noacg-paint', quizPaintSig());
}

// applySelection(): mark the contestant's pick, read from the hidden #f6. One state and this
// value carry every answer — there is deliberately no state per option.
function applySelection() {
  var options = document.querySelectorAll('.quiz-option');
  for (var i = 0; i < options.length; i++) options[i].classList.remove('quiz-sel');
  var row = quizRow(document.getElementById('f6').textContent);
  if (!row) return;                // nothing picked yet, or an unknown letter
  row.classList.add('quiz-sel');
  gsap.fromTo(row, { scale: 1.04 }, { scale: 1, duration: 0.25 / motionSpeed(), ease: 'back.out(1.6)' });
}

// applyLock(): the answer is locked in. The dimming says so; the MACHINE is what actually
// makes it final, by simply having no "select" arrow leaving this state. Neither this nor
// applySelection stamps the paint signature — they are PARTIAL painters (see quizPaintSig).
function applyLock() {
  var root = document.querySelector('.quiz');
  if (root) root.classList.add('quiz-locked');
}

// applyAudienceResult(): paint the per-answer percentages from #f7 ("34 | 52 | 9 | 5",
// row order) as a chip on each option row. textContent only — the numbers may one day arrive
// from an audience backend, and nothing that came from outside the studio runs as markup. An
// empty slot removes its chip, so a partial result renders honestly. Stamps the signature: it
// is the audience state's FULL paint (the verdict underneath was painted by revealAnswer).
function applyAudienceResult() {
  var src = document.getElementById('f7');
  var parts = String(src ? src.textContent : '').split('|');
  var options = document.querySelectorAll('.quiz-option');
  var any = false;
  for (var i = 0; i < options.length; i++) {
    var value = (parts[i] || '').trim();
    var chip = options[i].querySelector('.quiz-aud');
    if (!value) {
      if (chip) chip.parentNode.removeChild(chip);
      continue;
    }
    if (!chip) {
      chip = document.createElement('span');
      chip.className = 'quiz-aud';
      options[i].appendChild(chip);
    }
    var text = /%$/.test(value) ? value : value + '%';
    if (chip.textContent !== text) chip.textContent = text;
    any = true;
  }
  var root = document.querySelector('.quiz');
  if (root) {
    if (any) root.classList.add('quiz-audience');
    else root.classList.remove('quiz-audience');
  }
  markQuizPaint();
}

// paintQuizState(): repaint the board from the MACHINE's current state plus the fields. Both
// update() and snap recovery land here, for one reason each: a data write must never erase a
// selection the machine still holds (a live Update mid-lock used to wipe the lock visual while
// the state chip still said "Locked in"), and a snap replays states with suppressed callbacks,
// so the call-driven marks (selection, lock, reveal) have to be re-applied from the fields
// afterwards — which the recovery sequence's trailing update() does by calling this. In the
// entrance state (or with no machine at all) it paints the neutral board, exactly as the old
// unconditional clearReveal() did.
function paintQuizState() {
  var state = '';
  if (typeof noacgMachineState === 'function') {
    state = (noacgMachineState().groups || {}).main || '';
  }
  // Idempotence: an update() arrives per KEYSTROKE from a live-typing control page, and the
  // paint below carries motion (the verdict's pop, the pick's spring). Repaint only when the
  // state or the letters actually changed — fixing a typo in the question must not make the
  // correct row re-pop on air. Every painter stamps the signature; clearReveal removes it.
  var root = document.querySelector('.quiz');
  if (root && root.getAttribute('data-noacg-paint') === quizPaintSig()) return;
  if (state === 'audience') {
    // The verdict underneath repaints when it is MISSING (a recovery) or when it is on the
    // WRONG ROW — an operator who typed the answer key wrong has to be able to correct it on
    // air, and this state used to refuse: the guard asked only whether a verdict existed, so a
    // changed correct letter left the mark sitting on the old answer while the field said
    // otherwise (found 2026-08-06). Comparing the marked row against the letter keeps the
    // reason the guard exists — a live percentage edit still refreshes the chips alone, so
    // nothing re-pops per keystroke.
    var marked = document.querySelector('.quiz-option.quiz-correct');
    if (!marked || marked !== quizRow(document.getElementById('f5').textContent)) revealAnswer();
    applyAudienceResult();         // stamps
    return;
  }
  if (state === 'reveal') { revealAnswer(); return; }   // clears first, then paints + stamps
  clearReveal();
  if (state === 'selected' || state === 'locked') applySelection();
  if (state === 'locked' || state === 'sealed') applyLock();
  markQuizPaint();                 // this WAS a full repaint (clear + state's marks) — certify it
}

// update(data): SPX sends field values as JSON, e.g. {"f0":"…","f1":"Venus","f5":"B"}.
// Each value is written into the element whose id matches the field name (f0 -> id="f0");
// the correct letter (f5) lands in a hidden element that next() reads later.
function update(data) {
  var fields = (typeof data === 'string') ? JSON.parse(data) : data;
  for (var key in fields) {
    var el = document.getElementById(key);
    if (el) setFieldValue(el, fields[key]);
  }
  paintQuizState();                // fresh data on a neutral board stays neutral; a board whose
                                   // machine holds a pick, a lock or a verdict keeps showing it
  // Designs on a stage hold their lines to the rows they were drawn for (no-op otherwise).
  if (typeof fitStagedText === 'function') fitStagedText();
}

// revealAnswer(): the money moment — read the correct letter from the hidden #f5,
// light that option up ('quiz-correct'), fade the other three ('quiz-dim'), and give the
// winner a small spring pop.
function revealAnswer() {
  var letter = document.getElementById('f5').textContent.trim().toUpperCase();
  var index = 'ABCD'.indexOf(letter);        // A -> row 0, B -> row 1, …
  var options = document.querySelectorAll('.quiz-option');
  if (index === -1 || !options[index]) return;  // unknown letter — do nothing
  var picked = document.getElementById('f6');
  var pickedLetter = picked ? picked.textContent.trim().toUpperCase() : '';
  clearReveal();                   // a second Continue press stays clean
  for (var i = 0; i < options.length; i++) {
    options[i].classList.add(i === index ? 'quiz-correct' : 'quiz-dim');
  }
  // Pop the correct row: enter slightly enlarged, spring back to rest.
  gsap.fromTo(options[index],
    { scale: 1.06 },
    { scale: 1, duration: 0.45 / motionSpeed(), ease: 'back.out(2)' }
  );
  // A WRONG pick gets its own treatment — the criterion asks for the selected and the correct
  // answer to be told apart, not just for the right one to light up.
  if (pickedLetter && pickedLetter !== letter) {
    var wrong = quizRow(pickedLetter);
    if (wrong) {
      wrong.classList.remove('quiz-dim');
      wrong.classList.add('quiz-wrong');
      gsap.fromTo(wrong, { x: -6 }, { x: 0, duration: 0.4 / motionSpeed(), ease: 'elastic.out(1, 0.4)' });
    }
  }
  markQuizPaint();
}

// play(): take the quiz on air — start un-revealed, run the entrance timeline.
function play() {
  gsap.killTweensOf('*');          // stop any animation that is still running
  clearReveal();                   // replays always start with the answer hidden
  buildInTimeline();
}

// stop(): take the quiz off air — run the exit timeline.
function stop() {
  gsap.killTweensOf('*');
  buildOutTimeline();
}

// next(): SPX Continue — play the graphic's next step. Step 2 is the answer reveal: the
// animation data below fires revealAnswer() on it (see that step's "calls").
function next() {
  return (typeof revealNextStep === 'function') ? revealNextStep() : null;
}

/* == ANIMATION (generated — the Animation panel rewrites this block) == */
// The graphic's animation as DATA. Steps play in order — the first on ▶ play(), each
// middle step on one » next() press (SPX Continue), the last on ■ stop(). Each layer's
// properties are keyframe lists on the step's local clock: { "time", "value", "ease" }.
// "reveals" names the layers that first become visible in that step; "hides" names the
